import{_ as i}from"./index-dOcyQ9H1.js";import{az as l}from"./@vue-De9RwyRn.js";import"./element-plus-CKJIAC2w.js";import"./lodash-es-Ceiv_TW4.js";import"./@vueuse-Ihwzeb_o.js";import"./@element-plus-B-y2LHuz.js";import"./async-validator-j0i5Y79Y.js";import"./@popperjs-DxtSUbXb.js";import"./@ctrl-DGnlsNIE.js";import"./dayjs-KsS9adaU.js";import"./memoize-one-BAtLgO95.js";import"./normalize-wheel-es-TzhA1irr.js";import"./@floating-ui-BQjuueHq.js";import"./pinia-Dndd2XNl.js";import"./crypto-js-B6L3KfD1.js";import"./vue-i18n-DB7lm_w-.js";import"./@intlify-D8hALvN4.js";import"./vue-router-DNsliMEH.js";import"./pinia-plugin-persistedstate-COWkwNh5.js";const s=i({},[["render",function(i,s){return s[0]||(s[0]=l('<div class="helpBoxTop">一、基本配置</div><div class="helpBoxTopChild">TCP/IP设置</div><ul><li> 设备配备两张10M/100M/1000M网卡，工作模式选择“多址设定”时，两张网卡参数相互独立，网卡相互工作，可分别对LAN1和LAN2进行设置。工作模式选择“网络容错”时，两张网卡使用相同的IP地址。 </li><li> 网卡参数配置可以设置“网卡类型”、“设备IPv4地址”、“IPv4子网掩码”和“IPv4默认网关”。勾选自动获取，设备可自动获取网络地址及相关网络参数。设备不支持手动配置IPV6地址，只能自动获取。 </li><li>“MTU”项可以设置最大传输单元，指TCP/UDP协议网络传输中所通过的最大数据包的大小。</li><li>DNS服务器配置正确的可用服务器地址后，需要域名访问的功能才可正常使用。</li></ul><div class="helpDesText">相关参数修改后，单击“保存”按键来保存设置。</div><div class="helpBoxTopChild" style="margin-top:8px;">端口设置</div><div class="helpDesText" style="margin-top:8px;"> 端口配置参数包括：“HTTP端口”、“RTSP端口”、“HTTPS端口”和“服务端口”。通过网络访问设备时 可根据需要设置相应的端口。 </div><div class="helpDesText" style="margin-top:8px;"> 请不要随意修改缺省端口参数；当存在端口冲突需要修改端口号时，请对应修改如下信息： </div><ul><li> HTTP和HTTPS端口：使用浏览器登录时需要在地址后面加上修改的端口号。 如当HTTP端口号修改为81时，当您使用浏览器登录时，需要输入http://192.0.0.64:81。 </li><li>RTSP端口：实时传输协议端口，请确保您修改的端口可用即可。</li><li> 服务端口：当使用客户端登录到网络录像机时，当您修改了服务端口，您需要在登录界面输入端口号才能正常登录网络录像机。 </li></ul><div class="helpBoxTopChild">端口映射</div><div class="helpDesText" style="margin-top:8px;"> 启用端口映射，网络录像机的端口才能正常开放，端口映射方式分为“自动”和“手动”。 </div><ul><li> 选用“自动”模式，并启用UPnP™后，用户无需在路由器上做端口映射，只需在路由器上开启UPnP™功能； </li><li> 选择“手动”，用户需要手动在路由器上做端口映射。手动模式下，用户可以指定公网IP下要映射的外部端口，用户不需要修改网络摄像机自身的端口，如果路由器或网关不支持UPnP™功能，用户可以在这里填写当前映射的外部端口状态。 </li><li> 端口映射后状态一栏会显示是否生效，同时在外部端口中显示当前映射的公网IP下的外部端口，用户如果需要通过公网来访问网络摄像机，需要使用这个当前映射的外部端口来访问。 </li></ul><div class="helpBoxTop">二、高级配置</div><div class="helpBoxTopChild">SNMP设置</div><div class="helpDesText" style="margin-top:8px;"> 用户可通过SNMP协议实现对设备参数的获取和接收设备的报警异常信息。 </div><ul><li> 分别设置“写共同体名称”、“读共同体名称”，然后设置Trap管理地址，设备可向管理站发送报警和异常信息，通过设置Trap端口可接收设备的信息。 </li><li>相关参数修改后，需单击“保存”按键来保存相关设置。</li></ul><div class="helpDesText"> 说明： 设置SNMP参数前，用户需要下载SNMP软件，通过SNMP端口接收设备的信息。 </div><div class="helpBoxTop" style="margin-top:8px;">Email设置</div><div class="helpDesText" style="margin-top:8px;"> 通过设置邮件参数，当有报警发生时，可以发送邮件到指定的邮箱。 </div><ul><li> 输入SMTP服务器的地址、SMTP端口号、用户名、密码，以及发件人和收件人的邮箱名称、地址等信息，然后单击“保存”。 </li><li>勾选“启用SSL/TLS”，邮件发送将经过SSL/TLS加密后发送，此时SMTP端口号需更改为465。</li><li> 勾选“图片附件”，邮件中将附带即时抓图三张，用户可以设置抓图时间间隔。相关参数修改后，需单击“保存”按键来保存相关设置。 </li><li> 填写好收件人名称和地址后，用户可点击“测试”按钮来发送一封测试邮件，用户可查收件人邮件来确认是否发送成功。 </li><li>邮件内容中包括：设备通道名称，事件类型，事件日期时间，设备类型，设备序列号。</li><li>相关参数修改后，单击“保存”按键来保存设置。</li></ul><div class="helpBoxTopChild">平台接入设置</div><div class="helpDesText" style="margin-top:8px;"> 启用平台接入，网络录像机可以接入指定的国标28181、ISUP（原Ehome）或萤石云平台。平台接入功能与设备型号有关，请以实际设备为准。 </div><ol><li> 28181：28181接入是指遵循GB/T28181的要求，将网络录像机注册到公安网平台，然后通过公安网平台访问录像机，实现视音频点播、历史视音频的回放等操作。勾选“启用”，选择平台接入方式为28181，并设置其相关参数，即可实现28181接入。参数设置完毕后，单击“保存”完成设置。 <ul style="list-style-type:circle;"><li> 本地SIP端口：默认为5060，设置范围：1025~65535。如要修改，请以平台实际提供为准。 </li><li>SIP服务器ID：20位数字。由平台提供，即平台SIP服务器的ID。</li><li>SIP服务器域：10位数字。SIP服务器ID的前10位。</li><li>SIP服务器地址：即平台SIP服务器的IP地址，仅支持IPv4地址。</li><li> SIP服务器端口：即平台SIP服务器的端口号。服务器端口默认为5060，设置范围：1~65535。如要修改，请以平台实际提供为准。 </li><li>SIP用户认证ID：由平台提供，即设备的ID，20位数字。设备类型为111~118。</li><li> SIP用户认证密码：即平台注册密码，默认为12345678，最大31位字符。如要修改，请以平台实际提供为准。 </li><li>注册有效期：有效设置范围：100~100000，默认为3600。单位为秒。</li><li>心跳周期：有效设置范围：5~3600，默认为60。单位为秒。</li><li>最大心跳超时次数：有效设置范围：3~255，默认为5。单位为次。</li><li>速度类型：可设置选项：倍率、速率。默认倍率。</li><li> 倍率：当速度类型设置为倍率时，通过下拉框可选择的选项有：1/8、1/4、1/2、1、2、4、8，默认为2。当速度类型设置为速率时，可通过文本框输入，默认为2，单位为Kbps。 </li><li> 报警输入编码ID：28181A格式编码，由平台提供，即设备报警通道的ID，20位数字或空。设备类型为134。 </li><li> 视频通道编码ID：28181A格式编码，由平台提供，即设备视频通道的ID，20位数字或空。设备类型为131或132。 </li><div>说明：</div><li>当使能注册时，服务器IP、服务器域、服务器ID不能为空。</li><li>注册有效期、心跳周期、心跳次数建议保持默认。</li><li>支持启用私有信息。</li><li>启用、取消启用GB28181接入类型需要重启设备才能生效。</li></ul></li></ol><div class="helpBoxTopChild" style="margin-top:8px;">网络服务设置</div><div class="helpDesText" style="margin-top:8px;"> HTTPS协议是由SSL+HTTP协议构建的可进行加密传输、身份认证的网络协议，提高WEB访问安全性。 </div><div>说明：</div><ul><li> 若设备开启HTTPS服务，HTTPS端口有效范围：1~65535，采用HTTPS方式远程访问时，在浏览器地址栏输入https/IP地 址”；如果HTTPS设置443以外的端口，请在浏览器的地址栏输入https：/IP地址+： ：（冒号）+端口号，例如 https://192.0.0.64:81 </li></ul><div class="helpBoxTopChild">集成协议</div><div class="helpDesTxt"> 勾选“启用ONVIF认证”并配置ONVIF认证方式，默认选择“digest”认证方式。若三方平台只支持ws-username token认证，用户需要切换设备的认证方式为digest&amp;ws-username token。 </div>',28))}]]);export{s as default};
